gameActivityImportAdditions.insert:

import com.taptap.sdk.share.TapTapShareBuilder;
import android.content.Intent;
import android.net.Uri;
import java.io.File;
import java.util.ArrayList;

gameActivityClassAdditions.insert:

private static final int TAPSHARE_PICK_IMAGE_REQUEST = 61001;
private final ArrayList<Uri> mSharePickedImages = new ArrayList<>();

/** 唤起系统图片选择器（demo 用）。结果在 onActivityResult 注入处理 */
public void pickShareImage() {
    try {
        Intent i = new Intent(Intent.ACTION_GET_CONTENT);
        i.addCategory(Intent.CATEGORY_OPENABLE);
        i.setType("image/*");
        i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);
        startActivityForResult(Intent.createChooser(i, "Image Chooser"), TAPSHARE_PICK_IMAGE_REQUEST);
    } catch (Exception e) {
        android.util.Log.e("TapSDK_UE", "TapShare pickShareImage error: " + e.getMessage(), e);
    }
}

/** 返回已选图片的 URI 字符串数组（content:// 形式） */
public String[] getPickedShareImagePaths() {
    String[] arr = new String[mSharePickedImages.size()];
    for (int idx = 0; idx < mSharePickedImages.size(); idx++) {
        arr[idx] = mSharePickedImages.get(idx).toString();
    }
    return arr;
}

public int getPickedShareImageCount() { return mSharePickedImages.size(); }

public void clearPickedShareImages() { mSharePickedImages.clear(); }

public int shareToTapTap(String title, String contents, String hashtagIds,
                         String groupLabelId, String failUrl, String[] imagePaths) {
    try {
        TapTapShareBuilder builder = new TapTapShareBuilder();
        if (title != null && title.length() > 0)            { builder.addTitle(title); }
        if (contents != null && contents.length() > 0)      { builder.addContents(contents); }
        if (hashtagIds != null && hashtagIds.length() > 0)  { builder.addHashtagIds(hashtagIds); }
        if (groupLabelId != null && groupLabelId.length() > 0) { builder.addGroupLabelId(groupLabelId); }
        if (failUrl != null && failUrl.length() > 0)        { builder.addFailUrl(failUrl); }

        if (imagePaths != null && imagePaths.length > 0) {
            ArrayList<Uri> uris = new ArrayList<>();
            for (String p : imagePaths) {
                if (p != null && p.length() > 0) {
                    // 兼容图片选择器返回的 content:// 与本地 file 路径
                    if (p.startsWith("content://") || p.startsWith("file://")) {
                        uris.add(Uri.parse(p));
                    } else {
                        uris.add(Uri.fromFile(new File(p)));
                    }
                }
            }
            if (!uris.isEmpty()) { builder.addFooterImageUrls(uris); }
        }

        return builder.build().share(this);
    } catch (Exception e) {
        android.util.Log.e("TapSDK_UE", "TapShare error: " + e.getMessage(), e);
        return -2;
    }
}

gameActivityOnActivityResultAdditions.insert:

if (requestCode == TAPSHARE_PICK_IMAGE_REQUEST && resultCode == RESULT_OK
        && data != null && data.getData() != null) {
    // 单张替换，对齐 Android 原生 demo（DemoShareActivity.picList）
    mSharePickedImages.clear();
    mSharePickedImages.add(data.getData());
    android.util.Log.i("TapSDK_UE", "TapShare picked image: " + data.getData());
}
